def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n == 99:
        return 'D'

    if n == 1:
        return 'C' if opp[0] == 'C' else 'D'

    my_def = sum(1 for a in me if a == 'D')
    opp_def = sum(1 for a in opp if a == 'D')

    if opp_def == n:
        return 'D'

    if my_def == 0:
        if opp_def > 0:
            return 'D' if opp[-1] == 'D' else 'C'
        else:
            if n == 9:
                return 'D'
            return 'C'

    punished = False
    for i in range(n - 1):
        if me[i] == 'D' and opp[i + 1] == 'D':
            punished = True
            break

    if punished:
        if opp_def > n * 0.5:
            return 'D'
        return 'C'

    if opp[-1] == 'D' and me[-1] == 'C':
        return 'D'

    recent_opp_def = sum(1 for a in opp[-10:] if a == 'D')
    if recent_opp_def >= 4:
        return 'D' if opp[-1] == 'D' else 'C'

    if n >= 15 and (n + 1) % 8 == 0:
        return 'D'

    if n >= 98:
        return 'D'

    return 'C'
